        blurb: "the user teams library: the persona-relationship graph (positions wired by relationships)",
        advertise: true,
    },
    Sidecar {
        name: "secret", context_env: None,
        blurb: "the credential store: which services we are paired with and whether those pairings still work (metadata + status only — no verb reads a secret back)",
        advertise: true,
    },
    Sidecar {
        name: "component", context_env: None,
        blurb: "the component library: proven components in technology-scoped kits (reuse, don't re-invent)",
        advertise: true,
    },
    Sidecar {
        name: "ui", context_env: None,
        blurb: "the UI spec SDK: the primitive contract (`ui schema`) an AI emits UI as data against, `ui validate` to check a spec, and the global versioned UI-kit store (`ui kit`)",
        advertise: true,
    },
    Sidecar {
        name: "project", context_env: None,
        blurb: "list local projects + read/set the published marker",
        advertise: true,
    },
    Sidecar {
        name: "files", context_env: None,
        blurb: "the project's file tree with metrics + single-path stat",
        advertise: true,
